import re
from nltk.tokenize import word_tokenize

def identify_spans(sentence):
    tokens = word_tokenize(sentence)
    spans = []

    for i in range(len(tokens)):
        if tokens[i].lower() == 'yes':
            if i + 1 < len(tokens) and tokens[i+1].lower() =='ma'am' or tokens[i+1].lower() == 'it':
                continue
            spans.append((i, i+len('supported'), 'claim'))
        elif tokens[i].lower() == 'not':
            spans.append((i, i+len('some'), 'claim'))
        elif tokens[i].lower() == 'that':
            if i + 1 < len(tokens) and tokens[i+1].lower() == 'is':
                continue
            spans.append((i, i+len('a fact'), 'premise'))
        elif re.match(r'\b(president|senator)\b', tokens[i]):
            spans.append((i, i+len(tokens[i]), 'claim'))

    return''.join([sentence[:span[0]] + f'<{span[2]}>{' + sentence[span[0]:span[1]] + '</' + span[2] + '>' for span in spans])

