def identify_spans(sentence: str) -> str:
    spans = []
    if "voted" in sentence.lower():
        start = sentence.index("voted")
        end = start + len("voted")
        spans.append((start, end))
    if "supported" in sentence.lower():
        start = sentence.index("supported")
        end = start + len("supported")
        spans.append((start, end))

    output_sentence = sentence
    for start, end in sorted(spans, reverse=True):
        if "voted" in sentence[start:end]:
